<?php
require_once __DIR__.'/../includes/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];db()->prepare('UPDATE customers SET is_blacklisted=1-is_blacklisted WHERE id=?')->execute([$id]);flash('success','Customer security status updated.');header('Location: '.base('admin/customers.php'));exit;}
$view=(int)($_GET['view']??0);if($view){$s=db()->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$view]);$c=$s->fetch();$o=db()->prepare('SELECT * FROM orders WHERE customer_id=? ORDER BY id DESC');$o->execute([$view]);$adminTitle='Customer profile';include 'header.php';?><div class="cards"><div class="stat"><span>Customer</span><b><?=e($c['full_name'])?></b></div><div class="stat"><span>Orders</span><b><?=$c['total_orders']?></b></div><div class="stat"><span>Total spent</span><b><?=money($c['total_spent'])?></b></div><div class="stat"><span>Status</span><b><?=$c['is_blacklisted']?'Blacklisted':'Active'?></b></div></div><div class="panel"><h2>Contact</h2><p><?=e($c['phone'])?><br><?=e($c['phone2'])?><br><?=e($c['email'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$c['id']?>"><button class="button <?=$c['is_blacklisted']?'ghost':'red'?>" data-confirm="Change blacklist status?"><?=$c['is_blacklisted']?'Remove blacklist':'Blacklist customer'?></button></form></div><div class="panel"><h2>Purchase history</h2><div class="table-wrap"><table class="table"><tr><th>Order</th><th>Date</th><th>Total</th><th>Status</th></tr><?php foreach($o as $x):?><tr><td><a href="<?=base('admin/orders.php?view='.$x['id'])?>"><?=e($x['order_number'])?></a></td><td><?=e($x['created_at'])?></td><td><?=money($x['total'])?></td><td><?=e($x['status'])?></td></tr><?php endforeach;?></table></div></div><?php include 'footer.php';exit;}
$q=trim($_GET['q']??'');$s=db()->prepare('SELECT * FROM customers WHERE full_name LIKE ? OR phone LIKE ? ORDER BY total_spent DESC LIMIT 200');$s->execute(['%'.$q.'%','%'.$q.'%']);$rows=$s->fetchAll();$adminTitle='Customers';include 'header.php';?><div class="panel"><div class="panel-head"><h2>Customer directory</h2><form class="table-tools"><input class="search-input" name="q" value="<?=e($q)?>" placeholder="Search name or phone"><button class="button">Search</button></form></div><?php if(!$rows):?><div class="empty">No customers found.</div><?php else:?><div class="table-wrap"><table class="table"><tr><th>Customer</th><th>Phone</th><th>Orders</th><th>Total spent</th><th>Status</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['phone'])?></td><td><?=$r['total_orders']?></td><td><?=money($r['total_spent'])?></td><td><?=!empty($r['is_blacklisted'])?'<span class="tag status-rejected">Blacklisted</span>':'<span class="tag status-approved">Active</span>'?></td><td><a class="button" href="?view=<?=$r['id']?>">Profile</a></td></tr><?php endforeach;?></table></div><?php endif;?></div><?php include 'footer.php'; ?>
